mapper.select:
SELECT f.commodity_id AS commodityId, c.commodity_name AS commodityName, c.commodity_code AS commodityCode, c.cover_file_id AS coverFileId, c.status AS commodityStatus,
IFNULL((SELECT MIN(IFNULL(s2.sku_points_price, c.points_price)) FROM t_mall_sku s2 WHERE s2.commodity_id = f.commodity_id AND s2.sku_status = 1), c.points_price) AS pointsPrice, c.sold_count AS soldCount, COUNT(1) AS favoriteCount,
(SELECT IFNULL(SUM(s.available_stock), 0) FROM t_mall_sku s WHERE s.commodity_id = f.commodity_id AND s.sku_status = 1) AS availableStock FROM t_mall_favorite f INNER JOIN t_mall_commodity c ON c.id = f.commodity_id GROUP BY f.commodity_id, c.commodity_name, c.commodity_code, c.cover_file_id, c.status, c.points_price, c.sold_count ORDER BY favoriteCount DESC, c.sold_count ASC LIMIT #{topN}

SELECT f.commodity_id AS commodityId, c.commodity_name AS commodityName, c.commodity_code AS commodityCode, c.cover_file_id AS coverFileId, c.status AS commodityStatus,
IFNULL((SELECT MIN(IFNULL(s2.sku_points_price, c.points_price)) FROM t_mall_sku s2 WHERE s2.commodity_id = f.commodity_id AND s2.sku_status = 1), c.points_price) AS pointsPrice, c.sold_count AS soldCount, COUNT(1) AS favoriteCount,
(SELECT IFNULL(SUM(s.available_stock), 0) FROM t_mall_sku s WHERE s.commodity_id = f.commodity_id AND s.sku_status = 1) AS availableStock FROM t_mall_favorite f INNER JOIN t_mall_commodity c ON c.id = f.commodity_id GROUP BY f.commodity_id, c.commodity_name, c.commodity_code, c.cover_file_id, c.status, c.points_price, c.sold_count HAVING availableStock <= 0 OR commodityStatus != 1 ORDER BY favoriteCount DESC LIMIT #{topN}
